if (!params.thisUnit) return;
var attackType = params.effect.attackType?.name;
var melee =  attackType == "in melee" || attackType == "when charging";
if (melee && !weapon.melee) return;
if (attackType == "when shooting" && !weapon.ranged) return;
unit.quality -= params.effect.rollModifier.value;

if (params.thisUnit) return 0;
var weapon = { ...this.avgRangedWeapon, range: params.effect.attackType?.value ?? this.avgRangedWeapon.range };
var diff = (this.getWeaponCost(weapon, { quality: 5 - params.effect.rollModifier.value }) - this.getWeaponCost(weapon, { quality: 5 }));
return diff;

var { weaponRule1, weaponRule2 } = params.effect;
var range = params.assignment.inRange?.value ?? 12;
var weapon = { attacks: params.effect.numberDigit.value, range, rules: [] };
if (weaponRule1) {
  weapon.rules.push(weaponRule1.name);
  this.applyRating(weapon, weaponRule1);
}
if (weaponRule2) {
  weapon.rules.push(weaponRule2.name);
  this.applyRating(weapon, weaponRule2);
}
var cost = this.getWeaponCost(weapon, { quality: 1 })
var multiplier = params.assignment.target?.name === "model" ? this.SniperEffect : 1;
return cost * multiplier;

const { name, rating } = params.effect.unitRule;
const avgUnit = !params.thisUnit;
const skirmishAura = params.thisUnitAura && this._skirmish;
// Skirmish auras units must work out the cost on this unit AND avg units...
if (skirmishAura) {
  const auraSizes = this.calcSettings["AuraSizes"];
  const skirmishUnitSize = auraSizes["skirmish"];
  // How many units should be affected by the aura?
  const skirmishAuraUnitCount = auraSizes["skirmishAuraBuffUnitCount"];
  // -1 for "this unit"
  const affectingOtherUnits = skirmishAuraUnitCount - 1;
  const multiplier = skirmishUnitSize * skirmishAuraUnitCount;
  return [
    { name, rating }, // This unit
    { name, rating, multiplier, avgUnit } // Other units
  ];
} else {
  const auraSize = this.getAuraMultiplier(unit, params);
  const multiplier = params.multiplier * auraSize;
  return { name, rating, multiplier, avgUnit };
}

